"""Convergence of the arithmetic scattering-factor residue to 1/2."""
from __future__ import annotations
import mpmath as mp

def residue_estimate(k: int) -> float:
    """Return (s-1)*zeta(2s-1) for s = 1 + 10**(-k), approaching 1/2."""
    s = 1.0 + 10.0 ** (-k)
    return float((s - 1.0) * mp.zeta(2.0 * s - 1.0))

if __name__ == "__main__":
    for k in range(1, 9):
        print(f"s = 1 + 1e-{k}: (s-1)*zeta(2s-1) = {residue_estimate(k):.12f}")

"""Witness that zeta(2s-1) blows up as s -> 1 (genuine pole)."""
from __future__ import annotations
import mpmath as mp

def factor_magnitude(k: int) -> float:
    """Return |zeta(2s-1)| for s = 1 + 10**(-k); diverges as k grows."""
    s = 1.0 + 10.0 ** (-k)
    return float(abs(mp.zeta(2.0 * s - 1.0)))

if __name__ == "__main__":
    for k in range(1, 9):
        print(f"s = 1 + 1e-{k}: |zeta(2s-1)| = {factor_magnitude(k):.6e}")

